  return e.jsx('svg',{width:size,height:size,viewBox:'0 0 24 24',fill:'none',stroke:'currentColor',strokeWidth:1.7,strokeLinecap:'round',strokeLinejoin:'round','aria-hidden':true,focusable:false,'data-report-icon':report,children:(TR_NAV_ICONS[report]||TR_NAV_ICONS.default).map(([tag,props],index)=>e.jsx(tag,props,index))});
