function TRCleanUserGrants(value,sources,reports){
  const knownReports=new Set(reports.map(x=>x.id));
  const catalog=new Map(sources.map(x=>[x.key,x]));
  const removed=[];
  const grants=value.map(grant=>{
    const source=catalog.get(grant.source);
    if(!source||source.kind!=="reports"||grant.resources.includes("*"))return grant;
    const allowed=new Set((source.resources||[]).map(x=>x.id));
    const resources=grant.resources.filter(id=>{
      if(knownReports.has(id)&&!allowed.has(id)){
        removed.push({source:source.label,report:reports.find(x=>x.id===id)?.label||id});
        return false;
      }
      return true;
    });
    return {...grant,resources};
  }).filter(grant=>grant.resources.length>0);
  return {grants,removed};
}

const TR_PARAMS=new URLSearchParams(location.search);
const TR_CHANNEL=TR_PARAMS.get('client')==='toptop'&&['retail','online','wholesale'].includes(TR_PARAMS.get('channel'))?TR_PARAMS.get('channel'):'';
const TR_MARKETPLACES=TR_PARAMS.get('client')==='toptop'&&TR_PARAMS.get('channel')==='marketplaces';
const TR_RETAIL=TR_CHANNEL==='retail';
const TR_LABEL={retail:'Розница',online:'Интернет магазин',wholesale:'Опт'}[TR_CHANNEL]||'';
const TR_STORE=TR_PARAMS.get('store')||'';
if(TR_CHANNEL){
 document.documentElement.classList.add('trend-channel');
 if(TR_RETAIL)document.documentElement.classList.add('trend-retail');
 const preserve=(method)=>{const original=history[method].bind(history);history[method]=function(state,title,url){if(url){const next=new URL(url,location.href);if(next.searchParams.get('client')==='toptop'){next.searchParams.set('channel',TR_CHANNEL);if(TR_STORE)next.searchParams.set('store',TR_STORE)}url=next.pathname+next.search+next.hash}return original(state,title,url)}};
 preserve('replaceState');preserve('pushState');
 const originalFetch=window.fetch.bind(window);
 window.fetch=function(input,init){const url=new URL(typeof input==='string'?input:input instanceof URL?input.href:input.url,location.href);
  if(url.origin===location.origin&&url.pathname.startsWith('/api/')&&!url.pathname.startsWith('/api/admin/')&&!url.pathname.startsWith('/api/access/')&&!['/api/health','/api/database-status','/api/service-status'].includes(url.pathname)){
   url.searchParams.set('sales_channel',TR_CHANNEL);url.searchParams.set('client','toptop');if(TR_STORE)url.searchParams.set('store',TR_STORE);
   input=input instanceof Request?new Request(url,input):url.href;
  }return originalFetch(input,init);
 };
}
