const TRTerminalMarkets=[['wb','WB'],['ozon','Ozon'],['yandex_market','Яндекс Маркет'],['lamoda','Lamoda'],['avito','Avito'],['general','Общие']];
function TRTerminalMarket(text){
 const s=String(text||'').toLowerCase();
 if(/\bwb\b|wildberries|вайлдберриз/.test(s))return 'wb';
 if(/ozon|озон/.test(s))return 'ozon';
 if(/yandex|яндекс/.test(s))return 'yandex_market';
 if(/lamoda|ламода/.test(s))return 'lamoda';
 if(/avito|авито/.test(s))return 'avito';
 return '';
}
function TRTerminalGroups(logs){
 const groups=Object.fromEntries(TRTerminalMarkets.map(([key])=>[key,[]])), contexts=new Map();
 for(const row of logs||[]){
  const text=String(row.text||'');
  const client=(text.match(/^\[([^\]]+)\]/)||text.match(/^(?:> |Готово: |Не удалось запустить: )([^·]+)·/)||[])[1]?.trim();
  const explicit=TRTerminalMarket(text);
  if(client&&/^> /.test(text))contexts.set(client,explicit||'general');
  const market=TRTerminalMarket(row.marketplace)||explicit||(client?contexts.get(client):'')||'general';
  groups[market].push(row);
 }
 return groups;
}
